import random

random.seed(anonymous_student_id)

problem_value = random.randint(LOW, HIGH)
expected_answer = COMPUTE_EXPECTED_ANSWER_FROM(problem_value)

def check_answer(expect, ans):
    try:
        learner_value = float(ans)
    except (ValueError, TypeError):
        return {'ok': False, 'msg': '
Please enter a number.'}
    if abs(learner_value - expected_answer) < 1e-6 * max(1.0, abs(expected_answer)):
        return {'ok': True, 'msg': f'<p>Correct — the answer is {expected_answer}.</p>'}
    return {'ok': False, 'msg': f'<p>Not quite — expected {expected_answer}.</p>'}
